pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        MockToken token = new MockToken();
        address from = address(0x1);
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;
        c.transfer(from, address(token), tos, amounts);
        assertTrue(token.totalSupply() == 100);
    }
}

contract MockToken {
    uint256 public totalSupply;
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        totalSupply += amount;
        return true;
    }
}
